#include <stdio.h>
#include <stdlib.h>

FILE *open_file(const char *path, const char *mode) {
    FILE *file = fopen(path, mode);
    if (!file) { perror(path); exit(1); }
    return file;
}
void show_file(const char *path) {
    FILE *file = open_file(path, "r");
    int ch;
    while ((ch = fgetc(file)) != EOF) putchar(ch);
    fclose(file);
}
void copy_file(const char *source, const char *target) {
    FILE *in = open_file(source, "rb"), *out = open_file(target, "wb");
    int ch;
    while ((ch = fgetc(in)) != EOF) fputc(ch, out);
    fclose(in); fclose(out);
}

typedef struct { char name[32], address[32], health[32], education[32], sex; int num, age; double salary; } Employee;

int main(void) {
    int n, delete_number;
    scanf("%d", &n);
    FILE *file = open_file("employee", "w");
    for (int i = 0; i < n; i++) {
        Employee e;
        scanf("%31s%d %c%d%31s%lf%31s%31s", e.name, &e.num, &e.sex, &e.age, e.address, &e.salary, e.health, e.education);
        fprintf(file, "%s %d %c %d %s %.2f %s %s\n", e.name, e.num, e.sex, e.age, e.address, e.salary, e.health, e.education);
    }
    fclose(file);
    scanf("%d", &delete_number);
    FILE *source = open_file("employee", "r"), *wages = open_file("wages", "w");
    for (int i = 0; i < n; i++) {
        Employee e;
        if (fscanf(source, "%31s%d %c%d%31s%lf%31s%31s", e.name, &e.num, &e.sex, &e.age, e.address, &e.salary, e.health, e.education) != 8) return 1;
        fprintf(wages, "%d %.2f\n", e.num, e.salary);
    }
    fclose(source); fclose(wages);
    show_file("wages"); puts("AFTER");
    wages = open_file("wages", "r");
    FILE *updated = open_file("wages.tmp", "w");
    int number, count = 0;
    double salary;
    while (fscanf(wages, "%d%lf", &number, &salary) == 2) {
        if (number != delete_number) { fprintf(updated, "%d %.2f\n", number, salary); count++; }
    }
    fclose(wages); fclose(updated);
    if (remove("wages") != 0 || rename("wages.tmp", "wages") != 0) return 1;
    if (count) show_file("wages"); else puts("EMPTY");
    return 0;
}
